def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    depth = 0

    for char in paren_string:
        if char == " ":
            continue
        if char == "(":
            depth += 1
            current_group += char
        elif char == ")":
            depth -= 1
            current_group += char
            if depth == 0:
                result.append(current_group)
                current_group = ""

    return result

